            {
                EmptyTerms = new PdfPCell(new Phrase("", new Font(Font.FontFamily.TIMES_ROMAN, 11, Font.BOLD)));
                EmptyTerms.Border = 0;
                EmptyTerms.HorizontalAlignment = Element.ALIGN_LEFT;
                terms.AddCell(EmptyTerms);

                ph1 = new Phrase();
