        public void InvoiceFormat13(int Id)
        {
            DataSet ds = obj_report.TaxInvoicePrint13(Id);
            DataTable dt_inv = ds.Tables[0];
            DataTable dt_invD = ds.Tables[1];
            DataTable dt_cust = ds.Tables[2];
            DataTable dt_sum = ds.Tables[3];
            DataTable dtGeneral = ds.Tables[4];

            Document document = new Document(PageSize.A4, 20f, 20f, 10f, 10f);
            PdfWriter writer = PdfWriter.GetInstance(document, new FileStream(HttpContext.Current.Server.MapPath("~/PdfSave/" + (dt_inv.Rows[0]["Code"].ToString().Replace("/", "-")).Replace("\\", "-") + ".pdf"), FileMode.Create));

            document.Open();

            PdfPTable table1 = new PdfPTable(6);
            table1.DefaultCell.Padding = 4;
            float[] widths = new float[] { 25f, 15f, 10f, 12f, 10f, 18f };
