            DataSet ds = obj_report.CashReceiptPrint(Id);
            DataTable dt = ds.Tables[0];
            DataTable dtgen = ds.Tables[2];

            Document document = new Document(PageSize.A4, 10f, 10f, 10f, 0f);

            PdfWriter writer = PdfWriter.GetInstance(document, new FileStream(HttpContext.Current.Server.MapPath("~/PdfSave/" + (dt.Rows[0]["Code"].ToString().Replace("/", "-")).Replace("\\", "-") + ".pdf"), FileMode.Create));

            document.Open();
            if (dtgen.Rows[0]["PrintHeader"].ToString() != "")
            {

                string imageURL = Server.MapPath("../UploadedImage/" + dtgen.Rows[0]["PrintHeader"].ToString());
                iTextSharp.text.Image jpg = iTextSharp.text.Image.GetInstance(new Uri(imageURL));
                //Resize image depend upon your need
                jpg.ScaleToFit(550f, 450f);
                //Give space before image
                //jpg.SpacingBefore = 1f;
                //Give some space after the image
                jpg.SpacingAfter = 5f;
                jpg.Alignment = Element.ALIGN_CENTER;

                document.Add(jpg);
            }

