        public void CustomerSOAPdfFormat6(DateTime FromDate, DateTime ToDate, int CustomerId, int PaymentStatus, int CompletionStatus)
        {
            DataSet ds = obj_report.CustomerSOAPrintFormat6(FromDate, ToDate, CustomerId, PaymentStatus, CompletionStatus);
            DataTable dtCustomer = ds.Tables[0];
            DataTable dtDetails = ds.Tables[1];
            DataTable dtSum = ds.Tables[2];
            DataTable dtSubDetails = ds.Tables[3];
            DataTable dtgen = ds.Tables[4];

            Document document = new Document(PageSize.A4, 20f, 20f, 20f, 20f);

            string pdfDirectory = HttpContext.Current.Server.MapPath("~/PdfSave/");

            string formattedFromDate = FromDate.ToString("yyyy-MM-dd"); // Format as desired
            string formattedToDate = ToDate.ToString("yyyy-MM-dd");

            string pdfFileName = $"{dtCustomer.Rows[0]["Name"]}_{formattedFromDate}_{formattedToDate}.pdf";

            PdfWriter writer = PdfWriter.GetInstance(document, new FileStream(HttpContext.Current.Server.MapPath("~/PdfSave/" + pdfFileName), FileMode.Create));

            // PdfWriter writer = PdfWriter.GetInstance(document, new FileStream(HttpContext.Current.Server.MapPath("~/PdfSave/" + dtCustomer.Rows[0]["Id"].ToString() + ".pdf"), FileMode.Create));

            document.Open();
